import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
LOG_PATH = "/tmp/heron-work/requests.log"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive: 31 May 2025 inclusive

log = open(LOG_PATH, "a")


def note(msg):
    log.write(time.strftime("%H:%M:%S ") + msg + "\n")
    log.flush()


def raw_request(method, path, token=None):
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, dict(resp.headers), resp.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode("utf-8", "replace")


class Client:
    def __init__(self):
        self.token = None
        self.customers = {}
        self.customer_lookups = 0

    def get_token(self):
        for attempt in range(1, 20):
            status, headers, body = raw_request("POST", "/token")
            if status == 200:
                self.token = json.loads(body)["token"]
                note("token refreshed")
                return
            note(f"token attempt {attempt} status {status} body {body[:200]}")
            self.wait(headers, body, attempt)
        raise RuntimeError("could not obtain token")

    def wait(self, headers, body, attempt):
        delay = None
        ra = headers.get("Retry-After")
        if ra is not None:
            try:
                delay = float(ra)
            except ValueError:
                delay = None
        if delay is None:
            try:
                parsed = json.loads(body)
                for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
                    if key in parsed:
                        delay = float(parsed[key])
                        break
            except (ValueError, TypeError, AttributeError):
                pass
        if delay is None:
            delay = min(2 ** attempt, 60)
        note(f"sleeping {delay}s (Retry-After={ra})")
        time.sleep(delay + 0.5)

    def get_json(self, path, what):
        if self.token is None:
            self.get_token()
        for attempt in range(1, 40):
            status, headers, body = raw_request("GET", path, self.token)
            if status == 200:
                return json.loads(body)
            note(f"{what} attempt {attempt} status {status} body {body[:300]}")
            if status == 401:
                self.get_token()
                continue
            if status == 404:
                return None
            self.wait(headers, body, attempt)
        raise RuntimeError(f"gave up on {what}")

    def customer(self, cid):
        if cid not in self.customers:
            self.customer_lookups += 1
            self.customers[cid] = self.get_json(f"/customers/{cid}", f"customer {cid}")
        return self.customers[cid]


def parse_ts(s):
    s = s.strip()
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        raise ValueError("naive timestamp: " + s)
    return dt.astimezone(timezone.utc)


def main():
    client = Client()
    seen = {}
    duplicates = 0
    all_statuses = {}
    pages_visited = []
    anomalies = []

    path = "/orders?page=1"
    while path:
        page = client.get_json(path, f"orders {path}")
        pages_visited.append(page["page"])
        note(f"page {page['page']} of {page['total_pages']} items={len(page['items'])} next={page['next']}")
        for item in page["items"]:
            oid = item["id"]
            all_statuses[item["status"]] = all_statuses.get(item["status"], 0) + 1
            if oid in seen:
                duplicates += 1
                if seen[oid] != item:
                    anomalies.append(f"{oid} listed twice with differing content")
                continue
            seen[oid] = item
        path = page["next"]

    total_pages = page["total_pages"]
    if sorted(set(pages_visited)) != list(range(1, total_pages + 1)):
        anomalies.append(f"pages visited {sorted(set(pages_visited))} vs total_pages {total_pages}")
    if len(pages_visited) != len(set(pages_visited)):
        anomalies.append("a page was visited more than once")

    qualifying = []
    for oid, item in seen.items():
        if item["status"] != "shipped":
            continue
        ts = parse_ts(item["placed_at"])
        if not (START <= ts < END):
            continue
        qualifying.append(item)

    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    detail = []
    for item in qualifying:
        cust = client.customer(item["customer_id"])
        if cust is None:
            anomalies.append(f"order {item['id']} customer {item['customer_id']} not found (404)")
            continue
        pct = cust["discount_pct"]
        amt = item["amount_cents"]
        if not isinstance(amt, int) or not isinstance(pct, int):
            anomalies.append(f"non-integer value on {item['id']}: amount={amt!r} pct={pct!r}")
        num = amt * (100 - pct)
        # round half up to whole cent, per order (inputs are non-negative)
        discounted = (num + 50) // 100
        total += discounted
        region = cust["region"]
        by_region[region] = by_region.get(region, 0) + discounted
        detail.append((item["id"], item["placed_at"], amt, pct, discounted, region))

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    with open("/tmp/heron-work/detail.json", "w") as f:
        json.dump(detail, f)
    print(json.dumps(result, indent=2))
    print("distinct orders listed:", len(seen))
    print("status counts:", all_statuses)
    print("customer lookups (distinct cached):", client.customer_lookups)
    print("pages visited:", sorted(set(pages_visited)), "total_pages:", total_pages)
    print("anomalies:", anomalies if anomalies else "none")
    return result


if __name__ == "__main__":
    out = main()
    if "--write" in sys.argv:
        with open("/workspace/result.json", "w") as f:
            json.dump(out, f, indent=2)
            f.write("\n")
        print("wrote /workspace/result.json")

